.cr_transaction_vector<-function(x,name){if(is.list(x)&&is.null(names(x)))return(vapply(x,function(v).cr_sim_number(v,name),0.));.cr_numeric(x,name,vector_only=TRUE)}
.cr_transaction_cube<-function(value){
 cube<-if(inherits(value,'CalcResult'))value$value else value
 if(!.cr_object(cube)) .cr_error('TRANSACTION_CUBE','ScenarioCube required')
 .cr_data_required(cube,c('schema_version','kind','axes','scenario_ids','time_grid','factor_ids','values','weights','units','origin','frequency','probability_measure','sampling_contract'))
 if(cube$schema_version!='1.0'||cube$kind!='ScenarioCube'||!identical(unlist(cube$axes,use.names=FALSE),c('scenario','time','factor'))||cube$probability_measure!='PHYSICAL') .cr_error('TRANSACTION_CUBE','Physical ScenarioCube with declared scenario/time/factor axes required')
 for(k in c('scenario_ids','factor_ids')){ids<-unlist(cube[[k]],use.names=FALSE);if(!is.character(ids)||!length(ids)||anyNA(ids)||any(!nzchar(ids))||anyDuplicated(ids)) .cr_error('TRANSACTION_CUBE','Nonempty distinct axis IDs required')}
 times<-.cr_transaction_vector(cube$time_grid,'time_grid');weights<-.cr_transaction_vector(cube$weights,'weights');ns<-length(cube$scenario_ids);nt<-length(times);nf<-length(cube$factor_ids);v<-cube$values
 if(is.array(v)&&identical(as.integer(dim(v)),as.integer(c(ns,nt,nf)))){values<-v;.cr_numeric(v,'values')}else{
 if(!is.list(v)||length(v)!=ns) .cr_error('TRANSACTION_CUBE','Aligned scenario/time/factor values required')
 values<-array(0,c(ns,nt,nf));for(s in seq_len(ns)){if(!is.list(v[[s]])||length(v[[s]])!=nt) .cr_error('TRANSACTION_CUBE','Aligned scenario/time/factor values required');for(t in seq_len(nt)){row<-.cr_transaction_vector(v[[s]][[t]],'values');if(length(row)!=nf) .cr_error('TRANSACTION_CUBE','Aligned factor values required');values[s,t,]<-row}}
 }
 if(!nt||any(times<=0)||any(diff(times)<=0)||length(weights)!=ns||any(weights<0)||abs(sum(weights)-1)>1e-12) .cr_error('TRANSACTION_CUBE','Aligned finite axes and normalized nonnegative scenario weights required')
 units<-unlist(cube$units,use.names=FALSE);if(!is.character(units)||length(units)!=nf||anyNA(units)||any(!nzchar(units))) .cr_error('TRANSACTION_CUBE','Explicit factor units required')
 .cr_data_date(cube$origin,'origin');periods<-c(monthly=12,quarterly=4,annual=1)[cube$frequency]
 if(length(periods)!=1L||is.na(periods)||any(abs(times-seq_len(nt)/periods)>1e-12)) .cr_error('TRANSACTION_CALENDAR','Cube times must match declared monthly/quarterly/annual frequency')
 sampling<-cube$sampling_contract;if(!.cr_object(sampling)||!(sampling$law%in%c('FORECAST_CONDITIONAL','STATIONARY_GAUSSIAN','DECLARED_CYCLE_MIXTURE'))||is.null(sampling$conditioning_scope)||!nzchar(sampling$conditioning_scope)) .cr_error('TRANSACTION_CUBE','Explicit sampling law and conditioning scope required')
 list(cube=cube,values=values,weights=weights)
}
.cr_transaction_factor<-function(binding,cube,values,s,t){
 if(!.cr_object(binding)) .cr_error('TRANSACTION_BINDING','Explicit factor binding required')
 .cr_data_required(binding,c('factor_id','unit','transform'));k<-match(binding$factor_id,unlist(cube$factor_ids,use.names=FALSE))
 if(is.na(k)) .cr_error('TRANSACTION_BINDING','Unknown scenario factor')
 if(cube$units[[k]]!=binding$unit||!(binding$transform%in%c('level','exp'))) .cr_error('TRANSACTION_BINDING','Factor units and supported transformation must match')
 v<-values[s,t,k];if(binding$transform=='exp'){if(v<=-709||v>=709) .cr_error('NUMERICAL_FAILURE','Factor exponential exceeds finite range');v<-exp(v)};v
}
.cr_transaction_calendar_date<-function(origin,months){
 origin<-.cr_data_date(origin,'origin');yr<-as.integer(format(origin,'%Y'));mo<-as.integer(format(origin,'%m'));day<-as.integer(format(origin,'%d'));index<-yr*12+mo-1+months;y<-index%/%12;m<-index%%12+1
 last<-function(y,m){if(m==12)as.Date(sprintf('%04d-01-01',y+1))-1 else as.Date(sprintf('%04d-%02d-01',y,m+1))-1}
 d<-if(origin==last(yr,mo))as.integer(format(last(y,m),'%d'))else min(day,as.integer(format(last(y,m),'%d')))
 sprintf('%04d-%02d-%02d',y,m,d)
}
simulate_transactions<-function(transaction_recipes,scenario_cube,entity_innovations,parameter_snapshot,context=NULL){
