 .cr_sim_text(params$reserve_id,'reserve_id');if(params$reserve_id%in%c(seen$reserve,seen$asset)) .cr_error('TRANSACTION_DUPLICATE','Cash reserve cannot be reused across transactions');seen$reserve<-c(seen$reserve,params$reserve_id);initial_reserve<-.cr_sim_number(params$initial_reserve,'initial_reserve',0)
 calendar<-.cr_data_rows(recipe$calendar,'calendar');h<-length(cube$time_grid);if(length(calendar)!=h||length(params$reserve_targets)!=h||length(params$operating_base)!=h) .cr_error('TRANSACTION_CALENDAR','All transaction paths must cover shared scenario horizon')
