 recovered<-simulate_recovery_waterfall(events,recovery_claims,realizations,recovery$policy,context=ctx)$value
 for(s in seq_along(sids)){sid<-sids[s];path<-Filter(function(p)p$scenario_id==sid,path_results)[[1]];event<-path$default_event;loss<-sum(vapply(Filter(function(c)c$scenario_id==sid,recovered$claim_results),function(c)c$economic_loss,0.));trial_weight<-if(params$sampling_design=='IID_UNWEIGHTED')1 else weights[s];trials[[length(trials)+1L]]<-list(scenario_id=sid,subject_id=recipe$subject_id,initial_default=event$initial_default,defaulted=event$defaulted,horizon_complete=TRUE,weight=trial_weight,ead_at_default=path$ead_at_default,economic_loss=loss)}
 if(params$sampling_design=='IID_UNWEIGHTED'&&any(abs(weights-1/length(weights))>1e-14)) .cr_error('TRANSACTION_SAMPLING','IID trial declaration requires uniform scenario weights')
 contract<-list(contract_id=paste0(recipe$transaction_id,'::risk'),version=recipe$version,subject_id=recipe$subject_id,currency=currency,probability_measure='PHYSICAL',horizon=cube$time_grid[[h]],time_unit='years',conditioning='initially_performing',sampling_design=params$sampling_design,event='first_default',scenario_sampling_contract=cube$sampling_contract);risk<-estimate_simulation_risk(trials,contract,context=ctx)$value
 bundles[[length(bundles)+1L]]<-list(transaction_id=recipe$transaction_id,subject_id=recipe$subject_id,recipe_hash=.cr_hash(recipe),parameter_hash=recipe$parameter_hash,paths=path_results,default_assessment=detected,recovery=recovered,risk=risk,counterparty=counterparty)
 }
 if(!setequal(used,names(imap))) .cr_error('TRANSACTION_INNOVATION','Unused innovations rejected; shared channels may serve several declared drivers')
 .cr_result(list(transactions=bundles,scenario_cube_hash=.cr_hash(cube),parameter_snapshot_hash=.cr_hash(snapshot),innovation_hash=.cr_hash(innovations),sampling_contract=cube$sampling_contract),'simulation.simulate_transactions','transaction_paths',ctx,limitations='One complete legally pooled obligor per recipe, no implicit pooling of contractual compartments. Contractually scheduled nonnegative coupons; no extra interest on arrears, interest paid before principal. Cash dates include all payments; materiality is assumed continuous between dates without unrecorded cash. Independent outside-obligation evidence is caller supplied. Baseline contract receipts are included once; counterparty interruptions enter as cash changes, not an added borrower PD. Going-concern paths stop at first default; recovery uses that event, remaining actual exposure, collateral and reserve once. Recovery law here uses supplied fixed delays/costs/fractions and common default-date asset scenarios. Sampling law and PIT/TTC/stress conditioning are preserved, not inferred from an average.')
